queries.getEntry:
query GetEntry 
  (
      $id:ID!
  )
{
  getEntry
  (
      id:$id
  )

   {

    id
    title
    visibility
    notes
      author {

    id
    displayName
    tags
    __typename

      }
      related {

    id
    title
    visibility
    notes
    __typename

      }
    __typename

  }
}

queries.listEntries:
query ListEntries 
  (
      $visibility:Visibility,
      $limit:Int,
      $nextToken:String
  )
{
  listEntries
  (
      visibility:$visibility,
      limit:$limit,
      nextToken:$nextToken
  )

   {

      items {

    id
    title
    visibility
    notes
    __typename

      }
    nextToken
    __typename

  }
}

